#include "libs/provisioning/captive_portal_http.h"
#include "libs/provisioning/wifi_mgr_event.h"

#include <string.h>
#include <stdlib.h>
#include <stdio.h>

#include "esp_log.h"
#include "esp_wifi.h"
#include "freertos/FreeRTOS.h"
#include "freertos/queue.h"

static const char *TAG = "bkx_portal";

/* Embedded portal HTML — generated by CMake EMBED_TXTFILES */
extern const uint8_t portal_html_start[] asm("_binary_portal_html_start");
extern const uint8_t portal_html_end[]   asm("_binary_portal_html_end");

/* Queue passed in by WifiManager — used to post SAVE_CREDS events */
static QueueHandle_t s_event_queue = NULL;

/* ------------------------------------------------------------------ */
/*  Helpers                                                             */
/* ------------------------------------------------------------------ */

/**
 * @brief URL-decode src into dst (max_len includes null terminator).
 */
static void _urldecode(const char *src, char *dst, size_t max_len)
{
    size_t i = 0;
    size_t j = 0;
    while (src[i] != '\0' && j < max_len - 1) {
        if (src[i] == '%' && src[i + 1] != '\0' && src[i + 2] != '\0') {
            char hex[3] = { src[i + 1], src[i + 2], '\0' };
            dst[j++] = (char)strtol(hex, NULL, 16);
            i += 3;
        } else if (src[i] == '+') {
            dst[j++] = ' ';
            i++;
        } else {
            dst[j++] = src[i++];
        }
    }
    dst[j] = '\0';
}

/**
 * @brief Extract a URL-encoded form field value from an
 *        application/x-www-form-urlencoded body.
 *
 * @return true if the key was found (value may be empty).
 */
static bool _parse_form_field(const char *body, const char *key,
                               char *out, size_t out_len)
{
    char search[48];
    snprintf(search, sizeof(search), "%s=", key);

    const char *found = strstr(body, search);
    if (!found) {
        out[0] = '\0';
        return false;
    }
    found += strlen(search);

    const char *end  = strchr(found, '&');
    size_t value_len = end ? (size_t)(end - found) : strlen(found);

    char encoded[200] = { 0 };
    if (value_len >= sizeof(encoded)) {
        value_len = sizeof(encoded) - 1;
    }
    memcpy(encoded, found, value_len);
    encoded[value_len] = '\0';

    _urldecode(encoded, out, out_len);
    return true;
}

/**
 * @brief Escape a raw SSID string for inclusion in a JSON string value.
 *        Writes at most out_size-1 characters plus a null terminator.
 */
static size_t _json_escape(const char *src, char *out, size_t out_size)
{
    size_t j = 0;
    for (size_t i = 0; src[i] != '\0' && j + 2 < out_size; i++) {
        unsigned char c = (unsigned char)src[i];
        if (c == '"' || c == '\\') {
            if (j + 3 >= out_size) { break; }
            out[j++] = '\\';
            out[j++] = (char)c;
        } else if (c < 0x20) {
            /* skip control characters */
        } else {
            out[j++] = (char)c;
        }
    }
    out[j] = '\0';
    return j;
}

/* ------------------------------------------------------------------ */
/*  Handlers                                                            */
/* ------------------------------------------------------------------ */

static esp_err_t handler_portal_page(httpd_req_t *req)
{
    size_t html_len = (size_t)(portal_html_end - portal_html_start);
    /* EMBED_TXTFILES appends a null byte — exclude it from the response */
    if (html_len > 0 && portal_html_start[html_len - 1] == '\0') {
        html_len--;
    }
    httpd_resp_set_type(req, "text/html; charset=utf-8");
    httpd_resp_send(req, (const char *)portal_html_start, (ssize_t)html_len);
    return ESP_OK;
}

static esp_err_t handler_scan(httpd_req_t *req)
{
    /* Allocate record buffer */
    uint16_t max_records = 20;
    wifi_ap_record_t *records = calloc(max_records, sizeof(wifi_ap_record_t));
    if (!records) {
        httpd_resp_send_500(req);
        return ESP_FAIL;
    }

    /* Blocking scan — runs in the single-threaded httpd task.
     * Parallel requests are serialised by httpd, so no concurrent-scan guard needed. */
    esp_err_t err = esp_wifi_scan_start(NULL, true);
    if (err != ESP_OK) {
        ESP_LOGW(TAG, "Scan failed: %s", esp_err_to_name(err));
        free(records);
        httpd_resp_set_type(req, "application/json");
        httpd_resp_send(req, "[]", 2);
        return ESP_OK;
    }

    uint16_t count = max_records;
    esp_wifi_scan_get_ap_records(&count, records);
    /* esp_wifi_scan_get_ap_records also frees the internal scan list */

    /* Build JSON array — each entry: {"ssid":"...","rssi":-xx} */
    /* Maximum per entry: {"ssid":"<64-escaped>","rssi":-100}, = ~85 chars */
    size_t buf_size = (size_t)count * 96 + 8;
    char *buf = malloc(buf_size);
    if (!buf) {
        free(records);
        httpd_resp_send_500(req);
        return ESP_FAIL;
    }

    int pos = 0;
    pos += snprintf(buf + pos, buf_size - (size_t)pos, "[");

    /* Deduplicate SSIDs: skip if already emitted */
    bool emitted[20] = { false };
    for (uint16_t i = 0; i < count; i++) {
        if (emitted[i]) { continue; }
        /* Mark duplicates */
        for (uint16_t j = i + 1; j < count; j++) {
            if (strcmp((char *)records[i].ssid, (char *)records[j].ssid) == 0) {
                emitted[j] = true;
            }
        }

        char escaped_ssid[72];
        _json_escape((char *)records[i].ssid, escaped_ssid, sizeof(escaped_ssid));

        if (pos > 1) {
            pos += snprintf(buf + pos, buf_size - (size_t)pos, ",");
        }
        pos += snprintf(buf + pos, buf_size - (size_t)pos,
                        "{\"ssid\":\"%s\",\"rssi\":%d}",
                        escaped_ssid, records[i].rssi);
    }
    pos += snprintf(buf + pos, buf_size - (size_t)pos, "]");

    httpd_resp_set_type(req, "application/json");
    httpd_resp_send(req, buf, pos);

    free(buf);
    free(records);
    return ESP_OK;
}

static esp_err_t handler_save(httpd_req_t *req)
{
    /* Read body — WiFi + MQTT fields need more space */
    char body[512] = { 0 };
    int received = httpd_req_recv(req, body, sizeof(body) - 1);
    if (received <= 0) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Empty body");
        return ESP_FAIL;
    }
    body[received] = '\0';

    char ssid[33] = { 0 };
    char pass[65] = { 0 };

    if (!_parse_form_field(body, "ssid", ssid, sizeof(ssid)) || ssid[0] == '\0') {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Missing SSID");
        return ESP_FAIL;
    }
    _parse_form_field(body, "pass", pass, sizeof(pass)); /* password is optional */

    if (strlen(ssid) > 32 || strlen(pass) > 64) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Field too long");
        return ESP_FAIL;
    }

    /* Parse optional MQTT fields */
    char mqtt_uri[128]  = { 0 };
    char mqtt_user[65]  = { 0 };
    char mqtt_pass[65]  = { 0 };
    _parse_form_field(body, "mqtt_uri",  mqtt_uri,  sizeof(mqtt_uri));
    _parse_form_field(body, "mqtt_user", mqtt_user, sizeof(mqtt_user));
    _parse_form_field(body, "mqtt_pass", mqtt_pass, sizeof(mqtt_pass));

    /* Post event to WifiManager task — NVS write happens there, not here */
    if (s_event_queue) {
        wifi_mgr_event_t evt = { .type = WIFI_MGR_EVT_SAVE_CREDS };
        strncpy(evt.ssid,      ssid,      sizeof(evt.ssid) - 1);
        strncpy(evt.password,  pass,      sizeof(evt.password) - 1);
        strncpy(evt.mqtt_uri,  mqtt_uri,  sizeof(evt.mqtt_uri) - 1);
        strncpy(evt.mqtt_user, mqtt_user, sizeof(evt.mqtt_user) - 1);
        strncpy(evt.mqtt_pass, mqtt_pass, sizeof(evt.mqtt_pass) - 1);
        /* Non-blocking: if the queue is full the request is still acknowledged */
        if (xQueueSend(s_event_queue, &evt, 0) != pdTRUE) {
            ESP_LOGW(TAG, "Event queue full, credentials dropped");
        }
    }

    httpd_resp_set_type(req, "application/json");
    httpd_resp_send(req, "{\"status\":\"ok\"}", 15);
    return ESP_OK;
}

/**
 * @brief Generic handler for captive-portal OS detection probes.
 *        Returning the portal page (200) causes Android/iOS/Windows to show
 *        the "Sign in to network" notification.
 */
static esp_err_t handler_captive_probe(httpd_req_t *req)
{
    return handler_portal_page(req);
}

/* ------------------------------------------------------------------ */
/*  Public API                                                          */
/* ------------------------------------------------------------------ */

esp_err_t portal_http_start(httpd_handle_t *out_handle, QueueHandle_t event_queue)
{
    if (!out_handle) {
        return ESP_ERR_INVALID_ARG;
    }

    s_event_queue = event_queue;

    httpd_config_t config  = HTTPD_DEFAULT_CONFIG();
    config.server_port     = CONFIG_WIFI_MGR_PORTAL_PORT;
    config.lru_purge_enable = true;
    /* Extra URI slots: /, /scan, /save, + 4 captive-portal probes */
    config.max_uri_handlers = 8;

    esp_err_t err = httpd_start(out_handle, &config);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "Failed to start httpd: %s", esp_err_to_name(err));
        return err;
    }

    /* Main portal page */
    static const httpd_uri_t uri_root = {
        .uri = "/", .method = HTTP_GET, .handler = handler_portal_page,
    };
    httpd_register_uri_handler(*out_handle, &uri_root);

    /* Wi-Fi scan */
    static const httpd_uri_t uri_scan = {
        .uri = "/scan", .method = HTTP_GET, .handler = handler_scan,
    };
    httpd_register_uri_handler(*out_handle, &uri_scan);

    /* Credential save */
    static const httpd_uri_t uri_save = {
        .uri = "/save", .method = HTTP_POST, .handler = handler_save,
    };
    httpd_register_uri_handler(*out_handle, &uri_save);

    /* Captive-portal OS detection probes */
    static const httpd_uri_t uri_generate_204 = {
        .uri = "/generate_204", .method = HTTP_GET, .handler = handler_captive_probe,
    };
    httpd_register_uri_handler(*out_handle, &uri_generate_204);

    static const httpd_uri_t uri_hotspot = {
        .uri = "/hotspot-detect.html", .method = HTTP_GET, .handler = handler_captive_probe,
    };
    httpd_register_uri_handler(*out_handle, &uri_hotspot);

    static const httpd_uri_t uri_connecttest = {
        .uri = "/connecttest.txt", .method = HTTP_GET, .handler = handler_captive_probe,
    };
    httpd_register_uri_handler(*out_handle, &uri_connecttest);

    static const httpd_uri_t uri_ncsi = {
        .uri = "/ncsi.txt", .method = HTTP_GET, .handler = handler_captive_probe,
    };
    httpd_register_uri_handler(*out_handle, &uri_ncsi);

    ESP_LOGI(TAG, "Portal HTTP server started on port %d", CONFIG_WIFI_MGR_PORTAL_PORT);
    return ESP_OK;
}

esp_err_t portal_http_stop(httpd_handle_t handle)
{
    esp_err_t err = httpd_stop(handle);
    s_event_queue = NULL;
    return err;
}
